$ErrorActionPreference='Stop';
function GetEndpoint([string]$u){
  try{
    $r=Invoke-RestMethod -Uri $u -TimeoutSec 6;
    return [pscustomobject]@{ok=$true;url=$u;body=$r;error=''}
  }catch{
    return [pscustomobject]@{ok=$false;url=$u;body=$null;error=$_.Exception.Message}
  }
}
@(
  (GetEndpoint 'http://127.0.0.1:17448/api/status'),
  (GetEndpoint 'http://127.0.0.1:17448/api/operator-lifecycle'),
  (GetEndpoint 'http://127.0.0.1:17448/api/projects/control-plane?inspect=0'),
  (GetEndpoint 'http://127.0.0.1:17448/api/projects/control-plane/cutover-r42/status')
) | ConvertTo-Json -Depth 30 -Compress
